// Village / district info
// ---------------------------------------------------------------------------
// The map's land mass is drawn as 109 separate GIS path fragments (v1..v109)
// with no names attached in the source file. Fill in real village names and
// development info per id below as you identify which shape is which village
// (hover a shape in the running app and its data-district id is shown in the
// badge, e.g. "v42" -- match that id to the real village and add an entry
// here). Any id without an entry falls back to a generic placeholder via
// getVillageInfo() so the UI never breaks.
type VillageInfo = {
  name: string;
  population?: string;
  summary: string;
  highlights: string[];
};

const VILLAGES: Record<string, VillageInfo> = {
  // Example -- replace with real villages once ids are matched:
  // v42: {
  //   name: "Pago Pago",
  //   population: "\u2248 3,500",
  //   summary: "Harbor village and the territory's commercial hub.",
  //   highlights: [
  //     "Pago Pago Harbor upgrade underway",
  //     "Deep-water port serves the tuna canning industry",
  //   ],
  // },
};

function getVillageInfo(id: string): VillageInfo {
  return (
    VILLAGES[id] ?? {
      name: `Unnamed area (${id})`,
      summary: "No development information has been added for this area yet.",
      highlights: [],
    }
  );
}

